        {"kind": "log", "sql": "SELECT service_name, attr_k8s_pod_name pod, substr(message,1,300) m, min(time) t0, count(*) n FROM abnormal_logs WHERE service_name='ts-inside-payment-service' AND level='SEVERE' GROUP BY ALL", "claim": "Inside-payment logs 503 upstream connect errors from its call to payment, starting at 09:25:09."}
      ]
    },
    {
      "from": "ts-inside-payment-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95ms, round(avg(duration)/1e6,1) avgms FROM abnormal_traces WHERE attr_span_kind='Server' AND service_name='ts-ui-dashboard' AND span_name LIKE '%inside_pay%' GROUP BY ALL UNION ALL SELECT 'norm', service_name, span_name, count(*), round(quantile_cont(duration,0.95)/1e6,1), round(avg(duration)/1e6,1) FROM normal_traces WHERE attr_span_kind='Server' AND service_name='ts-ui-dashboard' AND span_name LIKE '%inside_pay%' GROUP BY ALL", "claim": "User-facing dashboard inside_payment requests slow to about 3 seconds on average, versus a much lower normal baseline."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind k, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(quantile_cont(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name='ts-inside-payment-service' AND span_name LIKE 'InsidePaymentController.pay%' GROUP BY ALL", "claim": "Inside-payment's pay controller has about 47% error spans and a p95 near 3.6 seconds in the abnormal window."}
      ]
    }
  ]
}
